export const emailTemplates: Record<string, string> = {"invitation": "<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"padding:32px;\">\n  <tr>\n    <td style=\"padding:0;\">\n      <!-- Badge de invitación -->\n      <table align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-bottom:20px;\">\n        <tr>\n          <td style=\"background-color:{company_primary_color}; border-radius:30px; padding:4px 14px;\">\n            <span style=\"color:white; font-size:12px; font-weight:600; letter-spacing:0.5px;\">INVITACIÓN A\n              FLYCONTROL</span>\n          </td>\n        </tr>\n      </table>\n\n      <h1 style=\"font-size:24px; font-weight:700; color:#0f172a; margin:0 0 8px 0; text-align:center;\">¡Únete a\n        FlyControl!</h1>\n      <p style=\"color:#334155; margin:0 0 8px 0; text-align:center;\">Estimado/a <strong>{full_name}</strong>,</p>\n      <p style=\"color:#334155; margin:0 0 24px 0; text-align:center;\">\n        <strong>{inviter_name}</strong> te ha invitado a formar parte de <strong>FlyControl</strong>, la plataforma\n        inteligente para gestionar tus vuelos, reservas y viajes de manera eficiente.\n      </p>\n\n      <!-- Breve descripción o mensaje (opcional pero mantiene el estilo) -->\n      <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n        style=\"background-color:#f8fafc; border-radius:16px; border:1px solid #e2e8f0; margin-bottom:24px;\">\n        <tr>\n          <td style=\"padding:20px;\">\n            <p style=\"color:#1e293b; margin:0 0 12px 0; font-size:14px;\">\n              Con FlyControl podrás:\n            </p>\n            <ul style=\"color:#334155; margin:0; padding-left:20px; font-size:14px;\">\n              <li>Centralizar todas tus reservas de vuelos</li>\n              <li>Recibir alertas de cambios y confirmaciones</li>\n              <li>Compartir viajes con otros usuarios</li>\n              <li>Acceder a tu historial desde cualquier dispositivo</li>\n            </ul>\n          </td>\n        </tr>\n      </table>\n\n      <!-- Botón de invitación -->\n      <table align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-top:8px;\">\n        <tr>\n          <td style=\"background-color:{company_primary_color}; border-radius:40px; padding:10px 28px;\">\n            <a href=\"{url_flycontrol}\" target=\"_blank\"\n              style=\"color:white; text-decoration:none; font-weight:600; font-size:14px; display:inline-block;\">\n              Aceptar invitación y unirme\n            </a>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>", "reservation_create": "<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"padding:32px;\">\n  <tr>\n    <td style=\"padding:0;\">\n      <!-- Badge \"RESERVA CREADA · PENDIENTE\" -->\n      <table align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-bottom:20px;\">\n        <tr>\n          <td style=\"background-color:{company_secondary_color}; border-radius:30px; padding:4px 14px;\">\n            <span style=\"color:white; font-size:12px; font-weight:600; letter-spacing:0.5px;\">RESERVA CREADA ·\n              PENDIENTE</span>\n          </td>\n        </tr>\n      </table>\n\n      <!-- Título y mensaje -->\n      <h1 style=\"font-size:24px; font-weight:700; color:#0f172a; margin:0 0 8px 0; text-align:center;\">¡Reserva\n        registrada con éxito!</h1>\n      <p style=\"color:#334155; margin:0 0 8px 0; text-align:center;\">Estimado/a <strong>{full_name}</strong>,</p>\n      <p style=\"color:#334155; margin:0 0 24px 0; text-align:center;\">Su reserva ha sido creada y está pendiente de\n        confirmación por parte del operador. En breve recibirás una actualización con el estado final.</p>\n\n      <!-- Código de reserva (estilo igual que antes) -->\n      <table align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n        style=\"background-color:#f1f5f9; border-radius:40px; margin:0 auto 24px auto;\">\n        <tr>\n          <td style=\"padding:8px 18px;\">\n            <span\n              style=\"font-family:monospace; font-size:18px; font-weight:600; color:{company_primary_color};\">{reservation_code}</span>\n          </td>\n        </tr>\n      </table>\n\n      <!-- Tarjeta de detalles (similar a la confirmada, pero con los campos solicitados) -->\n      <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n        style=\"background-color:#f8fafc; border-radius:16px; border:1px solid #e2e8f0; margin-bottom:24px;\">\n        <tr>\n          <td style=\"padding:20px;\">\n            <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n              <!-- Fila: Tipo de viaje -->\n              <tr>\n                <td style=\"padding-bottom:12px;\">\n                  <strong style=\"color:#334155;\">Tipo de viaje</strong><br>\n                  <span style=\"color:#1e293b;\">{tryp_type}</span>\n                </td>\n              </tr>\n              <!-- Fila: Ruta principal -->\n              <tr>\n                <td style=\"padding-bottom:12px;\">\n                  <strong style=\"color:#334155;\">Ruta principal</strong><br>\n                  <span style=\"color:#1e293b;\">{flight_origin} → {flight_destination}</span>\n                </td>\n              </tr>\n              <!-- Fila: Pasajero -->\n              <tr>\n                <td style=\"padding-bottom:12px;\">\n                  <strong style=\"color:#334155;\">Pasajero</strong><br>\n                  <span style=\"color:#1e293b;\">{full_name} · {nationality}</span>\n                </td>\n              </tr>\n              <!-- Fila: Contacto -->\n              <tr>\n                <td style=\"padding-bottom:0;\">\n                  <strong style=\"color:#334155;\">Contacto</strong><br>\n                  <span style=\"color:#1e293b;\">{passenger_phone}</span>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n      </table>\n\n      <!-- Botón \"Ver estado de reserva\" -->\n      <table align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-top:8px;\">\n        <tr>\n          <td style=\"background-color:{company_primary_color}; border-radius:40px; padding:10px 28px;\">\n            <a href=\"{url_view_details}\" target=\"_blank\"\n              style=\"color:white; text-decoration:none; font-weight:600; font-size:14px; display:inline-block;\">Ver\n              estado de reserva</a>\n          </td>\n        </tr>\n      </table>\n\n    </td>\n  </tr>\n</table>", "reservation_delete": "<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"padding:32px;\">\n  <tr>\n    <td style=\"padding:0;\">\n      <!-- Badge roja: RESERVA CANCELADA -->\n      <table align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-bottom:20px;\">\n        <tr>\n          <td style=\"background-color:#dc2626; border-radius:30px; padding:4px 14px;\">\n            <span style=\"color:white; font-size:12px; font-weight:600; letter-spacing:0.5px;\">RESERVA CANCELADA</span>\n          </td>\n        </tr>\n      </table>\n\n      <!-- Título y mensaje -->\n      <h1 style=\"font-size:24px; font-weight:700; color:#0f172a; margin:0 0 8px 0; text-align:center;\">Reserva cancelada\n      </h1>\n      <p style=\"color:#334155; margin:0 0 8px 0; text-align:center;\">Estimado/a <strong>{full_name}</strong>,</p>\n      <p style=\"color:#334155; margin:0 0 24px 0; text-align:center;\">Lamentamos informarte que tu reserva ha sido\n        cancelada. Si no solicitaste esta cancelación, por favor contáctanos de inmediato.</p>\n\n      <!-- Código de reserva (estilo consistente) -->\n      <table align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n        style=\"background-color:#f1f5f9; border-radius:40px; margin:0 auto 24px auto;\">\n        <tr>\n          <td style=\"padding:8px 18px;\">\n            <span\n              style=\"font-family:monospace; font-size:18px; font-weight:600; color:{company_primary_color};\">{reservation_code}</span>\n          </td>\n        </tr>\n      </table>\n\n      <!-- Tarjeta de detalles (solo tipo de viaje y ruta) -->\n      <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n        style=\"background-color:#f8fafc; border-radius:16px; border:1px solid #e2e8f0; margin-bottom:24px;\">\n        <tr>\n          <td style=\"padding:20px;\">\n            <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n              <!-- Fila: Tipo de viaje -->\n              <tr>\n                <td style=\"padding-bottom:12px;\">\n                  <strong style=\"color:#334155;\">Tipo de viaje</strong><br>\n                  <span style=\"color:#1e293b;\">{tryp_type}</span>\n                </td>\n              </tr>\n              <!-- Fila: Ruta principal -->\n              <tr>\n                <td style=\"padding-bottom:0;\">\n                  <strong style=\"color:#334155;\">Ruta principal</strong><br>\n                  <span style=\"color:#1e293b;\">{flight_origin} → {flight_destination}</span>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n      </table>\n      <!-- No hay botón en este caso, solo información -->\n    </td>\n  </tr>\n</table>", "reservation_confirm": "<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"padding:32px;\">\n  <tr>\n    <td style=\"padding:0;\">\n      <!-- Badverde -->\n      <table align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-bottom:20px;\">\n        <tr>\n          <td style=\"background-color:#10b981; border-radius:30px; padding:4px 14px;\"><span\n              style=\"color:white; font-size:12px; font-weight:600; letter-spacing:0.5px;\">RESERVA CONFIRMADA</span></td>\n        </tr>\n      </table>\n\n      <h1 style=\"font-size:24px; font-weight:700; color:#0f172a; margin:0 0 8px 0; text-align:center;\">¡Reserva\n        confirmada!</h1>\n      <p style=\"color:#334155; margin:0 0 8px 0; text-align:center;\">Estimado/a <strong>{full_name}</strong>,</p>\n      <p style=\"color:#334155; margin:0 0 24px 0; text-align:center;\">Su reserva ha sido confirmada. A continuación\n        encontrarás los detalles de tu viaje y los códigos de localizador (PNR) y ticket.</p>\n\n      <!-- Código de reserva -->\n      <table align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n        style=\"background-color:#f1f5f9; border-radius:40px; margin:0 auto 24px auto;\">\n        <tr>\n          <td style=\"padding:8px 18px;\"><span\n              style=\"font-family:monospace; font-size:18px; font-weight:600; color:{company_primary_color};\">{reservation_code}</span>\n          </td>\n        </tr>\n      </table>\n\n      <!-- Tarjeta de detalles -->\n      <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"\n        style=\"background-color:#f8fafc; border-radius:16px; border:1px solid #e2e8f0; margin-bottom:24px;\">\n        <tr>\n          <td style=\"padding:20px;\">\n            <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n              <tr>\n                <td style=\"padding-bottom:12px;\"><strong style=\"color:#334155;\">PNR</strong><br><span\n                    style=\"color:#1e293b;\">{tryp_pnr}</span></td>\n              </tr>\n              <tr>\n                <td style=\"padding-bottom:12px;\"><strong style=\"color:#334155;\">Número de ticket</strong><br><span\n                    style=\"color:#1e293b;\">{tryp_ticket}</span></td>\n              </tr>\n              <tr>\n                <td style=\"padding-bottom:12px;\"><strong style=\"color:#334155;\">Tipo de viaje</strong><br><span\n                    style=\"color:#1e293b;\">{tryp_type}</span></td>\n              </tr>\n              <tr>\n                <td style=\"padding-bottom:0;\"><strong style=\"color:#334155;\">Ruta principal</strong><br><span\n                    style=\"color:#1e293b;\">{flight_origin} → {flight_destination}</span></td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n      </table>\n\n      <!-- Botón -->\n      <table align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-top:8px;\">\n        <tr>\n          <td style=\"background-color:{company_primary_color}; border-radius:40px; padding:10px 28px;\">\n            <a href=\"{url_view_details}\" target=\"_blank\"\n              style=\"color:white; text-decoration:none; font-weight:600; font-size:14px; display:inline-block;\">Ver\n              estado de reserva</a>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>", "base": "<!DOCTYPE html>\n<html lang=\"es\">\n\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>{company_name} - Notificación de reserva</title>\n  <style>\n    /* Estilos generales (aplican en todos los clientes) */\n    @media only screen and (max-width: 600px) {\n\n      /* En móvil: quitamos padding del body y bordes redondeados */\n      body {\n        padding: 0 !important;\n        background-color: #ffffff !important;\n        /* evita que se vea el gris de fondo */\n      }\n\n      .main-container {\n        border-radius: 0 !important;\n        box-shadow: none !important;\n      }\n\n      .header-table {\n        border-radius: 0 !important;\n      }\n\n      .footer-table {\n        border-radius: 0 !important;\n      }\n\n      /* Opcional: ajusta el padding del contenido si lo deseas */\n      .content-padding {\n        padding: 16px !important;\n      }\n    }\n  </style>\n</head>\n\n<body\n  style=\"margin:0; padding:20px 0; background-color:#f4f7fb; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; line-height:1.5;\">\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\" bgcolor=\"#f4f7fb\"\n    style=\"background-color:#f4f7fb;\">\n    <tr>\n      <td align=\"center\" style=\"padding:0;\">\n        <!-- Tabla contenedora principal (se le asigna la clase main-container) -->\n        <table width=\"100%\" max-width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\"\n          class=\"main-container\"\n          style=\"max-width:600px; width:100%; background-color:#ffffff; border-radius:24px; box-shadow:0 8px 20px rgba(0,0,0,0.05);\">\n          <tr>\n            <td style=\"padding:0;\">\n              <!-- CABECERA (con clase header-table) -->\n              <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" class=\"header-table\"\n                style=\"background-color:{company_primary_color}; border-radius:24px 24px 0 0;\">\n                <tr>\n                  <td style=\"padding:16px 24px;\">\n                    <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                      <tr>\n                        <td align=\"left\" valign=\"middle\" style=\"padding:0;\">\n                          <img src=\"{company_logo}\" alt=\"{company_name}\" width=\"80\"\n                            style=\"display:block; max-width:80px; height:auto; border:0;\" />\n                        </td>\n                        <td align=\"right\" valign=\"middle\" style=\"padding-left:16px;\">\n                          <div style=\"color:white; font-size:18px; font-weight:700; margin-bottom:4px;\">{company_name}\n                          </div>\n                          <!-- <div style=\"color:white; font-size:8px; opacity:0.9;\">Boleto de viaje</div> -->\n                        </td>\n                      </tr>\n                    </table>\n                  </td>\n                </tr>\n              </table>\n              <!-- FIN CABECERA -->\n\n              {content}\n\n              <!-- FOOTER (con clase footer-table) -->\n              <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" class=\"footer-table\"\n                style=\"background-color:#f8fafc; border-top:1px solid #e2e8f0; border-radius:0 0 24px 24px;\">\n                <tr>\n                  <td style=\"padding:24px 32px; text-align:center; font-size:12px; color:#64748b;\">\n                    <p style=\"margin:0 0 8px 0;\">{company_name} · {company_phone} · {company_email}</p>\n                    <p style=\"margin:0 0 12px 0;\">{company_address}</p>\n                    <p style=\"margin:12px 0 0 0;\">© 2026 FlyControl – Gestión de vuelos. Todos los derechos reservados.\n                    </p>\n                    <p style=\"margin:8px 0 0 0;\"><a href=\"#\"\n                        style=\"color:{company_primary_color}; text-decoration:none;\">Política de privacidad</a></p>\n                  </td>\n                </tr>\n              </table>\n              <!-- FIN FOOTER -->\n            </td>\n        </table>\n  </table>\n  </td>\n  </tr>\n  </table>\n</body>\n\n</html>", "flight_reminder": "<!DOCTYPE html>\n<html>\n\n<head>\n    <meta charset=\"utf-8\">\n    <title>Recordatorio de Vuelo</title>\n</head>\n\n<body style=\"font-family: Arial, sans-serif; background-color: #f4f4f5; margin: 0; padding: 20px;\">\n    <table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\"\n        style=\"max-width: 600px; margin: auto; background-color: #ffffff; border-radius: 8px; overflow: hidden; box-shadow: 0 4px 6px rgba(0,0,0,0.05);\">\n        <tr>\n            <td style=\"background-color: {company_primary_color}; padding: 20px; text-align: center;\">\n                <img src=\"{company_logo}\" alt=\"{company_name}\" style=\"max-height: 50px; margin-bottom: 10px;\">\n                <h1 style=\"color: #ffffff; margin: 0; font-size: 22px;\">Recordatorio de Vuelo</h1>\n            </td>\n        </tr>\n        <tr>\n            <td style=\"padding: 30px;\">\n                <p style=\"font-size: 16px; color: #333;\">Hola <strong>{passenger_name}</strong>,</p>\n                <p style=\"font-size: 14px; color: #555; line-height: 1.5;\">\n                    Te recordamos que tu vuelo está programado para dentro de <strong>{time_left}</strong>.\n                </p>\n\n                <table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"10\"\n                    style=\"background-color: #f8fafc; border-radius: 8px; margin: 20px 0;\">\n                    <tr>\n                        <td style=\"border-bottom: 1px solid #e2e8f0;\">\n                            <strong style=\"color: #333;\">Vuelo:</strong> <span\n                                style=\"color: #555;\">{flight_number}</span>\n                        </td>\n                    </tr>\n                    <tr>\n                        <td style=\"border-bottom: 1px solid #e2e8f0;\">\n                            <strong style=\"color: #333;\">Ruta:</strong> <span style=\"color: #555;\">{origin} hacia\n                                {destination}</span>\n                        </td>\n                    </tr>\n                    <tr>\n                        <td>\n                            <strong style=\"color: #333;\">Salida:</strong> <span\n                                style=\"color: #555;\">{departure_time}</span>\n                        </td>\n                    </tr>\n                </table>\n\n                <p style=\"font-size: 14px; color: #555;\">\n                    Recuerda presentarte en el aeropuerto con al menos 3 horas de antelación y llevar tus documentos de\n                    viaje en regla.\n                </p>\n                <p style=\"font-size: 14px; color: #555; margin-top: 30px;\">\n                    ¡Buen viaje!<br>\n                    <strong>{company_name}</strong>\n                </p>\n            </td>\n        </tr>\n        <tr>\n            <td style=\"background-color: #f8fafc; padding: 15px; text-align: center; font-size: 12px; color: #888;\">\n                Si tienes dudas, contacta a {company_name} al {company_phone}.\n            </td>\n        </tr>\n    </table>\n</body>\n\n</html>"};
